  outline: var(--ds-focus-width, 3px) solid var(--ds-color-focus, #005fcc);
  outline-offset: var(--ds-focus-offset, 3px);
}

.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--ds-space-4, 8px);
