  padding: 10px var(--ds-space-6, 16px);
  border: var(--ds-border-width, 1px) solid transparent;
  border-radius: var(--ds-radius-control, 10px);
  background: var(--ds-color-action, #0066cc);
  color: var(--ds-color-on-action, #ffffff);
