  font-weight: var(--ds-font-weight-semibold, 600);
  line-height: var(--ds-line-height-ui, 1.4);
  transition: background-color var(--ds-duration-fast, 120ms) var(--ds-ease-standard, cubic-bezier(0.2, 0, 0, 1));
}

.ds-button--secondary {
  background: var(--ds-color-surface-subtle, #eeeef1);
  color: var(--ds-color-text, #1d1d1f);
}

.ds-button--danger {
  background: var(--ds-color-danger, #b42318);
  color: var(--ds-color-on-action, #ffffff);
}

.ds-button--ghost {
  background: transparent;
  color: var(--ds-color-action, #0066cc);
}

@media (hover: hover) {
  .ds-button:hover:not(:disabled) {
    background: var(--ds-color-action-hover, #005bb8);
    filter: none;
  }
  .ds-button--secondary:hover:not(:disabled),
.ds-button--ghost:hover:not(:disabled) {
    background: var(--ds-color-surface-hover, #e7e7ec);
  }
  .ds-button--danger:hover:not(:disabled) {
    background: var(--ds-color-danger-hover, #961d14);
  }
}

.ds-button:active:not(:disabled) {
  background: var(--ds-color-action-pressed, #004f9f);
  filter: none;
  transform: none;
}
.ds-button--secondary:active:not(:disabled),
.ds-button--ghost:active:not(:disabled) {
  background: var(--ds-color-surface-pressed, #dedee5);
}
.ds-button--danger:active:not(:disabled) {
  background: var(--ds-color-danger-pressed, #7c180f);
}
.ds-button:disabled {
  background: var(--ds-color-disabled-bg, #e7e7ec);
  color: var(--ds-color-text-disabled, #86868b);
  opacity: 1;
  cursor: not-allowed;
}
.ds-button[aria-busy="true"] {
  cursor: progress;
}

